import { describe, expect, it } from 'vitest';
import { boundsOf, centreOf, decodePolyline } from './polyline';

/**
 * FR-RTE-140's map layer rests entirely on this file: a wrong decoder draws a plausible
 * line through the wrong streets, which is worse than no line because nothing about it
 * looks broken.
 */
describe('encoded polyline', () => {
  /**
   * Google's own published example — `(38.5, -120.2) → (40.7, -120.95) → (43.252, -126.453)`.
   *
   * Taken from the algorithm's specification rather than generated by this decoder, which
   * is the entire point: a fixture produced by the code under test proves only that it is
   * self-consistent.
   */
  const GOOGLE_EXAMPLE = '_p~iF~ps|U_ulLnnqC_mqNvxq`@';

  it('decodes the specification’s own example', () => {
    const points = decodePolyline(GOOGLE_EXAMPLE);

    expect(points).toHaveLength(3);
    expect(points[0]?.lat).toBeCloseTo(38.5, 5);
    expect(points[0]?.lng).toBeCloseTo(-120.2, 5);
    expect(points[1]?.lat).toBeCloseTo(40.7, 5);
    expect(points[1]?.lng).toBeCloseTo(-120.95, 5);
    expect(points[2]?.lat).toBeCloseTo(43.252, 5);
    expect(points[2]?.lng).toBeCloseTo(-126.453, 5);
  });

  it('does not transpose latitude and longitude', () => {
    // The defect that puts a school bus in the Atlantic. The specification's example is
    // chosen for this: 38.5 and -120.2 cannot be mistaken for one another, so a decoder
    // that read the pair in the wrong order fails here rather than producing two
    // plausible Istanbul numbers that happen to be swapped.
    const [point] = decodePolyline(GOOGLE_EXAMPLE);

    expect(point?.lat).toBeCloseTo(38.5, 5);
    expect(point?.lng).toBeCloseTo(-120.2, 5);
    expect(point?.lat).toBeGreaterThan(0);
    expect(point?.lng).toBeLessThan(0);
  });

  it('answers empty for a route the fallback optimiser produced', () => {
    // FR-RTE-090's fallback computes an order, not a shape. `null` is a legitimate value
    // and the map draws the stops without a road line.
    expect(decodePolyline(null)).toEqual([]);
    expect(decodePolyline(undefined)).toEqual([]);
    expect(decodePolyline('')).toEqual([]);
  });

  it('answers empty for the fake provider’s marker rather than decoding nonsense', () => {
    expect(decodePolyline('fake:1,2,3')).toEqual([]);
  });

  it('returns what it managed to read from a truncated string, and does not throw', () => {
    // A corrupted or clipped value should cost the road shape, not the screen.
    const points = decodePolyline(GOOGLE_EXAMPLE.slice(0, 8));

    expect(() => decodePolyline(GOOGLE_EXAMPLE.slice(0, 8))).not.toThrow();
    expect(points.length).toBeLessThan(3);
  });

  it('round-trips a long path without drifting', () => {
    // Deltas accumulate: an off-by-one in the sign handling shows up as a path that
    // slowly wanders, which a three-point fixture would not catch.
    const points = decodePolyline(GOOGLE_EXAMPLE + GOOGLE_EXAMPLE);

    expect(points).toHaveLength(6);
    // The second copy resumes from where the first ended, which is the algorithm's own
    // semantics: every value is a delta, so the fourth point is the third plus the first
    // copy's opening offset. A decoder that reset its accumulator between segments — or
    // that treated the values as absolute — would answer 38.5 here.
    expect(points[3]?.lat).toBeCloseTo(43.252 + 38.5, 4);
    expect(points[3]?.lng).toBeCloseTo(-126.453 + -120.2, 4);
  });
});

describe('framing a map on what it shows', () => {
  const ISTANBUL = [
    { lat: 41.0082, lng: 28.9784 },
    { lat: 40.9903, lng: 29.0253 },
    { lat: 41.0255, lng: 29.0157 },
  ];

  it('bounds a set of points', () => {
    expect(boundsOf(ISTANBUL)).toEqual({
      north: 41.0255,
      south: 40.9903,
      east: 29.0253,
      west: 28.9784,
    });
  });

  it('has no bounds for no points', () => {
    expect(boundsOf([])).toBeNull();
    expect(centreOf([])).toBeNull();
  });

  it('centres between the extremes rather than on the mean of the points', () => {
    // A route with eleven stops in one street and one across the city should frame both,
    // not sit on top of the cluster.
    const centre = centreOf(ISTANBUL);

    expect(centre?.lat).toBeCloseTo((41.0255 + 40.9903) / 2, 6);
    expect(centre?.lng).toBeCloseTo((29.0253 + 28.9784) / 2, 6);
  });

  it('bounds a single point to itself', () => {
    const one = [{ lat: 41, lng: 29 }];

    expect(boundsOf(one)).toEqual({ north: 41, south: 41, east: 29, west: 29 });
  });
});
